from iteration18_browser_helpers import *
report={'docked':[], 'interruptions':[], 'keyboard':{}, 'shortWindow':{}, 'externalSubmission':False}
call('set','viewport','1440','1000');call('set','media','light');call('open','http://127.0.0.1:4321/');settle();center('.footer');call('click','.footer-booking [data-booking]');settle()
report['docked']=js('''(()=>{const page=document.querySelector('[data-booking-page]'),footer=document.querySelector('.footer'),b=footer.getBoundingClientRect(),r=e=>e.getBoundingClientRect(),issues=[];for(const e of footer.querySelectorAll('a,button,select')){const x=r(e);if(x.width&&(x.left<b.left-.5||x.right>b.right+.5))issues.push(e.textContent);}return{layout:document.documentElement.dataset.bookingLayout,page:r(page).width,footer:r(footer).width,columns:getComputedStyle(footer.querySelector('.footer-panel')).gridTemplateColumns,issues}})()''')
assert report['docked']['layout']=='docked' and not report['docked']['issues'],report['docked'];call('screenshot',str(ROOT/'docs/previews/round23-footer-docked.png'));call('press','Escape');settle()
call('set','viewport','1024','390');js('document.activeElement?.blur();scrollTo({top:0,behavior:"instant"})');settle();call('hover','.more-menu>summary');settle()
report['shortWindow']=js('''(()=>{const p=document.querySelector('.more-panel'),c=p.querySelector('.surface-content'),r=p.getBoundingClientRect();return{open:p.parentElement.open,bottom:r.bottom,height:r.height,client:c.clientHeight,scroll:c.scrollHeight,window:innerHeight}})()''')
assert report['shortWindow']['open'] and report['shortWindow']['bottom']<390 and report['shortWindow']['scroll']>report['shortWindow']['client'],report['shortWindow'];call('screenshot',str(ROOT/'docs/previews/round23-header-short-window.png'));call('press','Escape');settle()
call('set','viewport','1440','1000');js('document.activeElement.blur();scrollTo({top:0,behavior:"instant"})');settle();call('mouse','move','0','500')
report['interruptions']=js('''(async()=>{const h=document.querySelector('.site-header'),pose=()=>new DOMMatrix(getComputedStyle(h).transform).m42,rows=[];for(const y of [600,500,650,550,700,600]){const before=pose();scrollTo({top:y,behavior:'instant'});await new Promise(r=>requestAnimationFrame(r));rows.push({y,before,after:pose()});await new Promise(r=>setTimeout(r,65));}await new Promise(r=>setTimeout(r,500));return{rows,final:pose(),hidden:h.classList.contains('is-hidden')}})()''')
assert not report['interruptions']['hidden'] and abs(report['interruptions']['final'])<.1,report['interruptions']
# A keyboard user can return to a concealed header without a separate click.
js('document.activeElement.blur();scrollTo({top:850,behavior:"instant"})');settle();assert js('document.querySelector(".site-header").classList.contains("is-hidden")')
call('press','Tab');call('focus','.more-menu>summary');settle();assert js('!document.querySelector(".site-header").classList.contains("is-hidden")'),'focus reveals';call('press','Escape');call('mouse','move','0','500');js('document.activeElement.blur()')
# Footer controls remain keyboard-operable and the two instances stay synchronized.
center('.footer');call('focus','.footer [data-feedback-toggle]');call('press','Enter');report['keyboard']['feedbackSynced']=js('new Set([...document.querySelectorAll("[data-feedback-toggle]")].map(b=>b.getAttribute("aria-pressed"))).size===1');assert report['keyboard']['feedbackSynced'];call('press','Enter')
call('focus','.footer [data-theme-select]');call('select','.footer [data-theme-select]','dark');assert js('document.documentElement.dataset.theme==="dark"');call('reload');settle();assert js('document.documentElement.dataset.theme==="dark"');center('.footer');call('select','.footer [data-theme-select]','auto');report['keyboard']['themePersists']=True
call('errors');save('iteration23-additional',report);print('PASS docked footer, short-window popup, interrupted header, keyboard reveal and synced settings',flush=True)
